export const PET_ART = {
  idle: 'data:image/webp;base64,',
  done: 'data:image/webp;base64,',
  sleep: 'data:image/webp;base64,',
} as const

/** Key of one bundled expression. */
export type PetArtKey = keyof typeof PET_ART
